{
  "scenes": [
    {
      "scene_id": "S1",
      "name": "杂乱桌面",
      "location": "工位俯拍",
      "intent": "呈现开场痛点，制造代入感"
    },
    {
      "scene_id": "S2",
      "name": "三步整理",
      "location": "工位手部特写",
      "intent": "把方法拆成可执行动作"
    },
    {
      "scene_id": "S3",
      "name": "清爽收尾",
      "location": "工位正面中景",
      "intent": "给出结果与情绪落点"
    }
  ],
  "shots": [
    {
      "shot_id": "SH01",
      "scene": "S1",
      "description": "俯拍桌面：纸张、杯子、快递盒堆在键盘周围，画面略显拥挤，字幕打出“桌面越乱，大脑越忙”。"
    },
    {
      "shot_id": "SH02",
      "scene": "S2",
      "description": "手部特写：把正前方视线内的物品一次性推到侧面空位，右上角计时器从 3:00 开始倒数。"
    },
    {
      "shot_id": "SH03",
      "scene": "S2",
      "description": "中景：桌面只留下屏幕、键盘、笔和水，其余物品收进一个收纳盒，盒子被移出画面。"
    },
    {
      "shot_id": "SH04",
      "scene": "S3",
      "description": "正面中景：桌角放上固定小托盘，钥匙与工牌落入托盘中，人物坐下开始工作，计时器停在 0:00。"
    },
    {
      "shot_id": "SH05",
      "scene": "S3",
      "description": "定格俯拍整洁桌面，字幕收尾“把干扰搬走，专注自然回来”，叠加账号信息。"
    }
  ]
}
